from functools import lru_cache
@lru_cache(None)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)
print(fib(8))

coins, amount = [1, 3, 4], 6
inf = amount + 1
dp = [inf] * (amount + 1)
dp[0] = 0
for s in range(1, amount + 1):
    for c in coins:
        if c <= s:
            dp[s] = min(dp[s], dp[s - c] + 1)
print(dp[amount] if dp[amount] < inf else -1)

items, capacity = [(2, 3), (3, 4)], 5
dp = [0] * (capacity + 1)
for w, v in items:
    for c in range(capacity, w - 1, -1):
        dp[c] = max(dp[c], dp[c - w] + v)
print(dp[capacity])

from bisect import bisect_left
a = [3, 1, 2, 2, 4]
tails = []
for x in a:
    i = bisect_left(tails, x)
    if i == len(tails):
        tails.append(x)
    else:
        tails[i] = x
print(len(tails))

a, b = "abc", "ac"
dp = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
for i in range(1, len(a) + 1):
    for j in range(1, len(b) + 1):
        if a[i - 1] == b[j - 1]:
            dp[i][j] = dp[i - 1][j - 1] + 1
        else:
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
print(dp[-1][-1])

n, m = 2, 3
dp = [[0] * m for _ in range(n)]
dp[0][0] = 1
for i in range(n):
    for j in range(m):
        if i == 0 and j == 0:
            continue
        dp[i][j] = (dp[i - 1][j] if i else 0) + (dp[i][j - 1] if j else 0)
print(dp[-1][-1])

